
fn seeded(n:u64)->sha3::Shake256Reader{let mut h=Shake256::default();h.update(b"fixed-input-rng-anf-validation-v1");h.update(&n.to_le_bytes());h.finalize_xof()}
fn main(){let args:Vec<_>=std::env::args().collect();let ops=load_ops(&args[1]).unwrap();let(nq,nb,_,regs)=analyze_ops(ops.iter());assert!(args.len()>=5,"certified-region summary paths required");let mut ranges=Vec::new();for path in &args[4..]{let summary:serde_json::Value=serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();assert_eq!(summary["full_operation_count"].as_u64().unwrap(),ops.len()as u64);for region in summary["selected_disjoint_certified_regions"].as_array().unwrap(){let start=region[0].as_u64().unwrap()as usize;let end=region[1].as_u64().unwrap()as usize;assert!(start<=end&&end<ops.len()&&end-start<10000);ranges.push((start,end));}}ranges.sort_unstable_by_key(|(a,b)|(*a,std::cmp::Reverse(*b)));ranges.dedup();let mut selected=Vec::new();for(a,b)in ranges{if selected.last().map_or(true,|(_,end)|a>*end){selected.push((a,b));}}let mut skip=vec![false;ops.len()];let mut methods=[0usize;2];for(start,end)in &selected{let span=&ops[*start..=*end];if coeff_projection::prove(span){methods[0]+=1;}else if symbol_projection::prove(span){methods[1]+=1;}else{panic!("selected reset projection did not re-prove: {start}..{end}");}for i in *start..=*end{if matches!(ops[i].kind,OperationType::X|OperationType::CX|OperationType::CCX|OperationType::Swap){skip[i]=true;}}}let removed=skip.iter().filter(|v|**v).count();eprintln!("CERTIFIED_RESET_REWRITE regions={} removed_value_ops={} methods={methods:?}",selected.len(),removed);let rows:Vec<Vec<U256>>=std::fs::read_to_string(&args[2]).unwrap().lines().filter(|x|!x.trim().is_empty()).take(64).map(|x|x.split_whitespace().skip(1).map(|v|U256::from_str_radix(v.trim_start_matches("0x"),16).unwrap()).collect()).collect();assert!(!rows.is_empty()&&rows.iter().all(|x|x.len()==6));let cap=args.get(3).map(|x|x.parse().unwrap()).unwrap_or(32);let mut alg=GlobalAnf::new(cap);let mut dummy=seeded(0);let mut initial=Simulator::new(nq as usize,nb as usize,&mut dummy);let mut expected=[vec![0u64;regs[0].len()],vec![0u64;regs[1].len()]];for(lane,row)in rows.iter().enumerate(){for(reg,v)in regs[..4].iter().zip(&row[..4]){initial.set_register(reg,*v,lane);}for reg in 0..2{for i in 0..expected[reg].len(){expected[reg][i]|=(row[4+reg].bit(i)as u64)<<lane;}}}let initialq=initial.qubits.clone();let initialb=initial.bits.clone();drop(initial);let mut q=vec![GlobalAnf::constant(0);nq as usize];let mut b=vec![GlobalAnf::constant(0);nb as usize];let mut input_nodes=Vec::new();for reg in &regs{for wire in reg{let id=alg.dag.variable(false);input_nodes.push((id,*wire));let p=GlobalAnf::constant(id);match wire{QubitOrBit::Qubit(id)=>q[id.0 as usize]=p,QubitOrBit::Bit(id)=>b[id.0 as usize]=p}}}let mut base=GlobalAnf::constant(1);let mut stack=Vec::new();let start=std::time::Instant::now();let mut mr=0usize;let mut shadow_candidates=std::collections::BTreeMap::<usize,Vec<usize>>::new();
 for path in ["/home/hclau/ecdsa_research/prefilter-macro-20261016/additional/carry-helper-proof-spans.tsv","/home/hclau/ecdsa_research/prefilter-macro-20261016/additional/complete-helper-proof-spans.tsv","/home/hclau/ecdsa_research/prefilter-macro-20261016/additional/phase-lifetime-proof-spans.tsv","/home/hclau/ecdsa_research/prefilter-macro-20261016/additional/expanded-lifetime-proof-spans.tsv","/home/hclau/ecdsa_research/prefilter-macro-20261016/additional/opaque-closure-proof-spans.tsv","/home/hclau/ecdsa_research/prefilter-macro-20261016/additional/opaque-cleanup-epoch-proof-spans.tsv","opaque-tail-certified-v1-proof-spans.tsv"]{for line in std::fs::read_to_string(path).unwrap().lines().filter(|s|!s.is_empty()&&!s.starts_with('#')){let v:Vec<_>=line.split_whitespace().collect();let lo:usize=v[0].parse().unwrap();let hi:usize=v[1].parse().unwrap();assert!(lo<hi&&hi<=ops.len());
 // Whole-region replacements may contain complete earlier reset certificates,
 // but must never cut through one. Their intermediate states are not certified.
 let compatible=selected.iter().all(|(s,e)|hi<=*s||lo>*e||(lo<=*s&&hi>*e));
 if compatible{shadow_candidates.entry(lo).or_default().push(hi);}}}
 for ends in shadow_candidates.values_mut(){ends.sort_unstable_by(|a,b|b.cmp(a));ends.dedup();}
 let mut shadow_resume=0;let mut shadow_receipts=Vec::new();let mut shadow_attempts=0;let mut first_unknown_contracts=Vec::new();
 let mut first_caps=Vec::new();let mut first_q_rng=Vec::new();let mut first_q_opaque=Vec::new();
 for(i,o)in ops.iter().enumerate(){if i<shadow_resume{continue;}
 if let Some(ends)=shadow_candidates.get(&i){let entry_zeros:std::collections::BTreeSet<u64>=q.iter().enumerate().filter(|(_,p)|p.0.iter().all(|(_,c)|alg.dag.find(*c)==0)).map(|(id,_)|id as u64).collect();for end in ends {shadow_attempts+=1;let span=&ops[i..*end];let local_millis=if i==5521782{10000}else{2000};let mut cert=shadow_value_contract(span,500000,local_millis);let mut required=Vec::new();if !cert.proved {cert=shadow_value_contract_with_zeros(span,500000,local_millis,&entry_zeros);if cert.proved {required=cert.quantum_ids.iter().filter(|id|entry_zeros.contains(id)).copied().collect();}}
 if !cert.proved&&first_unknown_contracts.len()<24 {first_unknown_contracts.push(serde_json::json!({"start":i,"end_exclusive":end,"status":cert.status,"unresolved_q_outputs":cert.quantum_ids.iter().zip(&cert.choices).filter(|(_,c)|**c==2).map(|(q,_)|*q).collect::<Vec<_>>(),"known_zero_entries":cert.quantum_ids.iter().filter(|q|entry_zeros.contains(q)).copied().collect::<Vec<_>>(),"nodes":cert.nodes,"caps":cert.caps}));}
 if cert.proved {for wire in &required {assert!(q[*wire as usize].0.iter().all(|(_,c)|alg.dag.find(*c)==0),"unproved entry-zero precondition");}let added=shadow_apply_region(span,&mut alg,&mut q,&mut b,&base,&cert);mr+=added;shadow_resume=*end;let reset=cert.choices.iter().filter(|c|**c==1).count();let receipt=serde_json::json!({"start":i,"end_exclusive":end,"required_proved_zero_entry_wires":required,"quantum_outputs":cert.quantum_ids.len(),"actual_guard_reset_outputs":reset,"zero_internal_mr_outputs":cert.quantum_ids.len()-reset,"remaining_rng_supported_q_outputs":cert.quantum_ids.iter().filter(|id|q[**id as usize].0.iter().any(|(k,c)|!k.is_empty()&&alg.dag.find(*c)!=0)).copied().collect::<Vec<_>>(),"local_nodes":cert.nodes,"local_caps":cert.caps,"source_region_digest_shake256_256":cert.operation_digest.iter().map(|b|format!("{b:02x}")).collect::<String>(),"mr":added});eprintln!("APPLIED_SHADOW_CONTRACT {receipt}");shadow_receipts.push(receipt);break;}}
 if i<shadow_resume {continue;}}
 if skip[i]{continue;}let before_caps=alg.capped;use OperationType::*;if matches!(o.kind,Neg|Z|CZ|CCZ|Register|AppendToRegister|DebugPrint){continue;}if o.kind==PopCondition{base=stack.pop().unwrap();continue;}let c=if o.c_condition.0==u64::MAX{base.clone()}else{alg.and(&base,&b[o.c_condition.0 as usize])};let t=o.q_target.0 as usize;let bt=o.c_target.0 as usize;let writing=matches!(o.kind,CCX|CX|X|Swap|R|Hmr);let had_rng=writing&&first_q_rng.len()<32&&q[t].0.iter().any(|(k,v)|!k.is_empty()&&alg.dag.find(*v)!=0);let had_opaque=writing&&first_q_opaque.len()<32&&q[t].0.iter().any(|(k,v)|alg.dag.find(*v)!=0&&k.iter().any(|x|alg.opaque_symbols.contains(x)));let c_support=if writing&&(first_q_rng.len()<32||first_q_opaque.len()<32){c.0.iter().filter(|(k,v)|!k.is_empty()&&alg.dag.find(*v)!=0).count()}else{0};match o.kind{CCX=>{let v=alg.and(&q[o.q_control1.0 as usize],&q[o.q_control2.0 as usize]);let v=alg.and(&v,&c);q[t]=alg.xor(&q[t],&v);},CX=>{let v=alg.and(&q[o.q_control1.0 as usize],&c);q[t]=alg.xor(&q[t],&v);},X=>q[t]=alg.xor(&q[t],&c),Swap=>{let a=o.q_control1.0 as usize;let v=alg.xor(&q[t],&q[a]);let v=alg.and(&v,&c);q[t]=alg.xor(&q[t],&v);q[a]=alg.xor(&q[a],&v);},R|Hmr=>{mr+=1;let random=alg.fresh();let nc=alg.not(&c);q[t]=alg.and(&q[t],&nc);if o.kind==Hmr{let old=alg.and(&b[bt],&nc);let new=alg.and(&random,&c);b[bt]=alg.xor(&old,&new);}},BitStore0=>{let nc=alg.not(&c);b[bt]=alg.and(&b[bt],&nc);},BitStore1=>{let nc=alg.not(&c);let old=alg.and(&b[bt],&nc);b[bt]=alg.xor(&old,&c);},BitInvert=>b[bt]=alg.xor(&b[bt],&c),PushCondition=>{stack.push(base);base=c;},_=>unreachable!()}
 if writing&&first_q_rng.len()<32&&!had_rng&&q[t].0.iter().any(|(k,v)|!k.is_empty()&&alg.dag.find(*v)!=0){let event=(i,format!("{:?}",o.kind),t,c_support);eprintln!("FIRST_QUANTUM_RNG_TAINT {event:?}");first_q_rng.push(event);}if writing&&first_q_opaque.len()<32&&!had_opaque&&q[t].0.iter().any(|(k,v)|alg.dag.find(*v)!=0&&k.iter().any(|x|alg.opaque_symbols.contains(x))){let event=(i,format!("{:?}",o.kind),t,c_support);eprintln!("FIRST_QUANTUM_OPAQUE_TAINT {event:?}");first_q_opaque.push(event);}if alg.capped>before_caps&&first_caps.len()<32{first_caps.push((i,format!("{:?}",o.kind),alg.capped-before_caps));}if i%500000==0{eprintln!("GLOBAL_RNG_PROGRESS ops={i} input_nodes={} caps={} fresh_symbols={} seconds={:.1}",alg.dag.nodes.len(),alg.capped,alg.next,start.elapsed().as_secs_f64());}}

 assert!(stack.is_empty());let seconds=start.elapsed().as_secs_f64();let mut output_roots=Vec::new();let mut dependent=0;for reg in&regs[..2]{for wire in reg{let p=match wire{QubitOrBit::Qubit(id)=>&q[id.0 as usize],QubitOrBit::Bit(id)=>&b[id.0 as usize]};let rng=p.0.iter().any(|(k,v)|!k.is_empty()&&alg.dag.find(*v)!=0);dependent+=usize::from(rng);output_roots.push(if rng{None}else{Some(p.0.iter().find(|(k,_)|k.is_empty()).map(|(_,c)|*c).unwrap_or(0))});}}
 // Evaluate only immutable input-only DAG coefficients on a concrete batch.
 // Measurement and capped-unknown symbols never enter this DAG.
 let mut values=vec![0u64;alg.dag.nodes.len()];values[1]=u64::MAX;for(id,wire)in&input_nodes{values[*id as usize]=match wire{QubitOrBit::Qubit(id)=>initialq[id.0 as usize],QubitOrBit::Bit(id)=>initialb[id.0 as usize]};}for(i,node)in alg.dag.nodes.iter().enumerate().skip(2){assert!(!node.random,"RNG-tainted expression entered an input-only coefficient");match node.kind{2=>{},3=>values[i]=values[node.a as usize]^values[node.b as usize],4=>values[i]=values[node.a as usize]&values[node.b as usize],7=>values[i]=alg.dag.large_defs[node.a as usize].iter().fold(0,|a,m|a^alg.dag.monomials[*m as usize].iter().fold(u64::MAX,|a,j|a&values[*j as usize])),8=>values[i]=[node.a,node.b].iter().fold(u64::MAX,|a,m|a&alg.dag.monomials[*m as usize].iter().fold(u64::MAX,|a,j|a&values[*j as usize])),_=>panic!("unexpected coefficient node")}}
 let concrete=|p:&GlobalPoly|{let(mut c,mut d)=(0,0);for(k,v)in&p.0{if k.is_empty(){c^=values[*v as usize]}else{d|=values[*v as usize]}}(c,!d)};let mask=if rows.len()==64{u64::MAX}else{(1u64<<rows.len())-1};let mut wrong=0;let(mut knownbits,mut allbits)=(0usize,0usize);for(reg,expected)in regs[..2].iter().zip(expected.iter()){for(wire,e)in reg.iter().zip(expected){let p=match wire{QubitOrBit::Qubit(id)=>&q[id.0 as usize],QubitOrBit::Bit(id)=>&b[id.0 as usize]};let(c,k)=concrete(p);wrong|=(c^e)&k&mask;knownbits+=(k&mask).count_ones()as usize;allbits+=rows.len();}}
 for seed in 0..4{let mut random=seeded(seed);let mut sim=Simulator::new(nq as usize,nb as usize,&mut random);sim.qubits.copy_from_slice(&initialq);sim.bits.copy_from_slice(&initialb);sim.apply_iter(ops.iter());for(i,p)in q.iter().enumerate(){let(c,k)=concrete(p);assert_eq!((sim.qubits[i]^c)&k,0,"global quantum containment wire{i} seed{seed}");}for(i,p)in b.iter().enumerate(){let(c,k)=concrete(p);assert_eq!((sim.bits[i]^c)&k,0,"global classical containment wire{i} seed{seed}");}for lane in 0..rows.len(){if wrong>>lane&1!=0{assert!(sim.get_register(&regs[0],lane)!=rows[lane][4]||sim.get_register(&regs[1],lane)!=rows[lane][5]);}}}
 let report=serde_json::json!({"stream_path":args[1],"shadow_contract_attempts":shadow_attempts,"applied_shadow_contracts":shadow_receipts,"first_unknown_contracts":first_unknown_contracts,"term_cap":cap,"certified_reset_regions":selected.len(),"reproved_region_methods_coeff_then_symbols":methods,"removed_quantum_value_ops":removed,"original_mr_positions_preserved":true,"input_only_dag_nodes":alg.dag.nodes.len(),"symbolic_input_wires":input_nodes.len(),"all_auxiliary_wires_initial_zero":true,"rng_draws":mr,"fresh_symbols_including_all_inactive_mr_and_opaque_unknowns":alg.next,"capped_expressions":alg.capped,"retained_opaque_nodes":alg.intern.len(),"retained_opaque_hits":alg.hits,"retained_opaque_clears":alg.clears,"output_bits":output_roots.len(),"unresolved_rng_dependent_bits":dependent,"proved_value_rng_independent":dependent==0&&output_roots.len()==512,"output_input_dag_roots":output_roots,"output_rng_support_sizes":regs[..2].iter().flat_map(|reg|reg.iter()).map(|wire|{let p=match wire{QubitOrBit::Qubit(id)=>&q[id.0 as usize],QubitOrBit::Bit(id)=>&b[id.0 as usize]};p.0.iter().filter(|(k,v)|!k.is_empty()&&alg.dag.find(*v)!=0).count()}).collect::<Vec<_>>(),"retained_input_large_definitions":alg.dag.large_defs.len(),"first_rng_cap_operation_events":first_caps,"first_quantum_rng_taint_events_original_indices":first_q_rng,"first_quantum_opaque_taint_events_original_indices":first_q_opaque,"concrete_validation_shots":rows.len(),"concrete_known_output_bits":knownbits,"concrete_total_output_bits":allbits,"concrete_certified_wrong_shots":wrong.count_ones(),"concrete_certified_wrong_mask":format!("{wrong:016x}"),"protected_full_state_containment_seeds":4,"seconds":seconds,"method":"global_rng_after_universal_and_prefix_guarded_local_shadow_contracts","status":"RESEARCH_PROOF_NOT_ENABLED_FOR_SCREENING"});println!("{report}");}
